/* totals.h: the promise. */
#ifndef TOTALS_H
#define TOTALS_H
#include <stddef.h>                          /* for size_t. */
int total(const int *values, size_t count);  /* declaration only. */
#endif

/* totals.c: the one definition. */
#include "totals.h"
int total(const int *values, size_t count) {
    int sum = 0;
    for (size_t i = 0; i < count; i++) sum += values[i];
    return sum;
}

/* main.c: a caller. */
#include <stdio.h>
#include "totals.h"
int main(void) {
    int marks[] = {7, 9, 8};
    printf("%d\n", total(marks, 3));        /* 24. */
    return 0;
}
